#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

banner "DailyWork — conectar contas da Fila (LinkedIn, X, Reddit)"

say "O DailyWork precisa estar ABERTO durante este wizard (ele já está rodando)."
say "As credenciais são coladas direto no app: menu Conexões → conta → aba Conta."
say "Nada é digitado neste terminal: aqui só há instruções e confirmações."
note "Se o GitHub já estiver autenticado no `gh`, pule essa conta."

# ── LinkedIn: criar o app ─────────────────────────────────────────────────
stage "LinkedIn · criar o app no portal"
say "O DailyWork pede os escopos openid profile email w_member_social, que vêm"
say "dos produtos 'Sign In with LinkedIn using OpenID Connect' e 'Share on LinkedIn'."
open_url "https://www.linkedin.com/developers/apps/new"
step "Nome do app: DailyWork (ou similar)."
step "Em 'LinkedIn Page', associe uma página sua. Se não tiver, crie uma em"
say "    https://www.linkedin.com/company/setup/new (leva 1 min, pode ser pessoal)."
step "Aceite os termos e clique em 'Create app'."
pause "App criado no LinkedIn?"

# ── LinkedIn: produtos, redirect e credenciais ────────────────────────────
stage "LinkedIn · produtos, redirect e credenciais"
say "Ainda no portal do app recém-criado:"
step "Aba 'Products': clique 'Request access' em 'Share on LinkedIn' e em"
say "    'Sign In with LinkedIn using OpenID Connect' (ambos aprovam na hora)."
step "Aba 'Auth' → 'OAuth 2.0 settings' → adicione o redirect URL exato:"
say "    http://localhost:47831/callback"
step "Na mesma aba 'Auth', copie o 'Client ID' e o 'Client Secret'."
say ""
say "Agora no DailyWork (app aberto):"
step "Conexões → LinkedIn → aba 'Conta'."
step "Cole Client ID e Client Secret nos campos e clique 'Salvar'."
step "Clique 'Autorizar no navegador' → o navegador abre → faça login e autorize."
note "O retorno cai em http://localhost:47831/callback e a página confirma sozinha."
pause "LinkedIn autorizado e status 'conectada' no DailyWork?"

# ── X: criar projeto/app ──────────────────────────────────────────────────
stage "X (Twitter) · criar projeto e app"
say "O plano Free do developer portal já permite postar (1.500 posts/mês)."
open_url "https://developer.x.com/en/portal/dashboard"
step "Crie um Project (ex.: 'DailyWork') e dentro dele um App."
step "Guarde a chave que ele mostrar na criação, mas o que importa vem no"
say "    próximo estágio (Client ID do OAuth 2.0)."
pause "Projeto e app criados no portal do X?"

# ── X: OAuth 2.0 e credencial ─────────────────────────────────────────────
stage "X (Twitter) · OAuth 2.0, callback e autorização"
say "O DailyWork pede: tweet.read tweet.write users.read offline.access media.write."
step "No app → 'Settings' → 'User authentication settings' → 'Set up'."
step "App permissions: 'Read and write'."
step "Type of app: 'Native App' (cliente público com PKCE — sem client secret)."
step "Callback URI exata: http://127.0.0.1:47832/callback"
step "Website URL: https://site.example"
step "Salve e copie o 'Client ID' que aparece."
say ""
say "No DailyWork:"
step "Conexões → X → aba 'Conta' → cole o Client ID → 'Salvar'."
step "Clique 'Autorizar no navegador' → autorize com sua conta do X."
pause "X autorizado e status 'conectada' no DailyWork?"

# ── Reddit: app script ────────────────────────────────────────────────────
stage "Reddit · app script e credenciais"
say "Reddit usa concessão por senha (app tipo script): sem dança de navegador."
open_url "https://www.reddit.com/prefs/apps"
step "Role até 'create app': nome 'DailyWork', tipo 'script'."
step "Campo 'redirect uri' é obrigatório mas não é usado: http://localhost"
step "Após criar: o client ID é o texto logo ABAIXO do nome do app, e o"
say "    secret aparece na linha 'secret'."
say ""
say "No DailyWork:"
step "Conexões → Reddit → aba 'Conta' → preencha Client ID, Client Secret,"
say "    usuário e senha do Reddit → 'Salvar'. O status já vira conectado."
pause "Reddit salvo e 'conectado' no DailyWork?"

# ── Verificação ───────────────────────────────────────────────────────────
stage "Verificação final"
VAULT="$HOME/.config/DailyWork/integracoes.json"
if [[ -f "$VAULT" ]]; then
  printf '  %s✓ cofre de credenciais existe:%s %s\n' "$GREEN" "$RESET" "$VAULT"
else
  warn "cofre ainda não existe em $VAULT — alguma conta ficou sem salvar?"
  SKIPPED+=("cofre de credenciais não encontrado; refaça o estágio da conta que faltou")
fi
say "Na Fila do DailyWork, os dots ao lado das contas devem estar verdes e os"
say "cards pendentes devem mostrar 'conta ✓' com o botão 'Publicar agora'."
note "Se algum dot continuar vermelho, reabra a conta em Conexões e confira o erro na aba Conta."

finish
